/*
 * CampsiteRatingControllerTest.kt
 * Purpose: US 01.13.01 eligibility, submission, per-stay updates and error tests.
 * Uses an isolated persistence fake; no Firebase connection is needed.
 */
package com.example.code.controller

import com.example.code.data.CampsiteRatingStore
import com.example.code.model.Rating
import com.example.code.model.Reservation
import com.example.code.model.averageRating
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

class CampsiteRatingControllerTest {
    private val now = 10_000L
    private val stay = Reservation(
        id = "jasper-stay-1", campsiteId = "jasper", entrantId = "priya",
        startDate = 100L, endDate = 200L,
    )
    private val store = Ratings()
    private val controller = CampsiteRatingController(store) { now }

    @Test fun completedStaySavesTheEntrantCampsiteReservationAndScore() = runBlocking {
        controller.submit("jasper", "priya", stay, 5)
        assertEquals(listOf(Rating(stay.id, "priya", "jasper", 5, stay.id)), store.rows.value)
    }

    @Test fun ratingTheSameStayAgainUpdatesItsScoreRatherThanAddingAnotherRating() = runBlocking {
        controller.submit("jasper", "priya", stay, 5)
        controller.submit("jasper", "priya", stay, 2)
        assertEquals(1, store.rows.value.size)
        assertEquals(2, store.rows.value.single().score)
        assertEquals(2.0, averageRating(store.rows.value)!!, 0.0)
    }

    @Test fun repeatedIdenticalSubmissionRemainsOneRating() = runBlocking {
        repeat(3) { controller.submit("jasper", "priya", stay, 4) }
        assertEquals(1, store.rows.value.size)
    }

    @Test fun twoStaysAtTheSameCampsiteContributeSeparateRatings() = runBlocking {
        controller.submit("jasper", "priya", stay, 5)
        controller.submit("jasper", "priya", stay.copy(id = "jasper-stay-2"), 1)
        assertEquals(2, store.rows.value.size)
        assertEquals(3.0, averageRating(store.rows.value)!!, 0.0)
    }

    @Test fun anotherEntrantCannotRateThisStay() {
        invalid(stay, entrant = "liam")
    }

    @Test fun anotherCampsiteCannotBeRatedUsingThisStay() {
        invalid(stay, campsite = "banff")
    }

    @Test fun futureAndOngoingStaysCannotBeRated() {
        invalid(stay.copy(startDate = now + 1, endDate = now + 100))
        invalid(stay.copy(endDate = now + 1))
        invalid(stay.copy(endDate = now))
    }

    @Test fun cancelledRejectedAndDeclinedStaysCannotBeRated() {
        listOf(Reservation.STATUS_CANCELLED, Reservation.STATUS_REJECTED, STATUS_DECLINED).forEach {
            invalid(stay.copy(status = it))
        }
    }

    @Test fun missingOrMalformedStayDoesNotGrantEligibility() {
        invalid(stay.copy(id = ""))
        invalid(stay.copy(endDate = 0))
        invalid(stay.copy(startDate = 300))
    }

    @Test fun scoresOutsideOneThroughFiveAreRejectedBeforePersistence() {
        listOf(Int.MIN_VALUE, -1, 0, 6, Int.MAX_VALUE).forEach { invalid(stay, score = it) }
        assertEquals(0, store.writes)
    }

    @Test fun allEligibleStaysAreReturnedNewestFirstIncludingPreviouslyRatedStays() {
        val later = stay.copy(id = "jasper-stay-2", endDate = 500)
        val all = listOf(stay, later, stay, stay.copy(id = "other", entrantId = "liam"))
        assertEquals(listOf(later, stay), rateableStays(all, "jasper", "priya", now))
        assertTrue(rateableStays(all, "", "priya", now).isEmpty())
        assertTrue(rateableStays(all, "jasper", "", now).isEmpty())
    }

    @Test fun failedSavePropagatesAndDoesNotInventASavedScore() {
        store.failWrites = true
        assertThrows(IllegalStateException::class.java) {
            runBlocking { controller.submit("jasper", "priya", stay, 4) }
        }
        assertTrue(store.rows.value.isEmpty())
    }

    @Test fun controllerUsesTheCurrentClockWhenSavingRatherThanScreenEligibilityTime() {
        var clock = now
        val live = CampsiteRatingController(store) { clock }
        val currentStay = stay.copy(endDate = now + 10)
        assertThrows(IllegalArgumentException::class.java) {
            runBlocking { live.submit("jasper", "priya", currentStay, 5) }
        }
        clock += 11
        runBlocking { live.submit("jasper", "priya", currentStay, 5) }
        assertFalse(store.rows.value.isEmpty())
    }

    private fun invalid(value: Reservation, campsite: String = "jasper", entrant: String = "priya", score: Int = 3) {
        assertThrows(IllegalArgumentException::class.java) {
            runBlocking { controller.submit(campsite, entrant, value, score) }
        }
        assertTrue(store.rows.value.isEmpty())
    }

    private class Ratings : CampsiteRatingStore {
        val rows = MutableStateFlow<List<Rating>>(emptyList())
        var failWrites = false
        var writes = 0
        override fun observeRatings(campsiteId: String, entrantId: String) = rows
        override suspend fun saveRating(campsiteId: String, reservationId: String, entrantId: String, score: Int) {
            check(!failWrites) { "Offline" }
            writes++
            val rating = Rating(reservationId, entrantId, campsiteId, score, reservationId)
            rows.value = rows.value.filterNot { it.id == reservationId } + rating
        }
    }
}
